}

method ReplaceSpaces(s: string) returns (v: string)
    ensures |v| >= |s|
    ensures forall i :: 0 <= i < |s| ==> (IsSpace(s[i]) ==> exists j :: 0 <= j <= |v| - 3 && v[j..j+2] == "%20") && (s[i] != ' ' ==> v[i + offset] == s[i])
